// Error Trigger payload depends on the failing node/trigger type.
// Send concise diagnostic context, NOT raw execution data, credentials or HTTP bodies.
const x = $input.first().json || {};
const exec = x.execution || {};
const wf = x.workflow || {};
const trig = x.trigger || {};
const raw = exec.error?.message || trig.error?.message || x.error?.message || 'Unknown workflow error';
const msg = String(raw).replace(/[\r\n]+/g, ' ').slice(0,1000);
const id = String(exec.id || 'N/A');
const name = String(wf.name || 'Unknown workflow').slice(0,120);
const node = String(exec.lastNodeExecuted || trig.node?.name || 'N/A').slice(0,120);
const when = new Date().toISOString();
return [{json:{email_subject:`[Deckdrive] AWARIA n8n — ${name}`,
  email_body:[
    'DECKDRIVE — BLAD TECHNICZNY WORKFLOW', '',
    `Workflow: ${name}`, `Node: ${node}`, `Execution ID: ${id}`, `Time UTC: ${when}`,
    `Blad: ${msg}`, '',
    'Sprawdz n8n > Executions oraz Worker Task State /task/lock.',
    'NIE uruchamiaj Codexa ponownie bez sprawdzenia stanu.',
    'Uwaga: Error Trigger dziala dla automatycznych wywolan, NIE manualnego Execute workflow.'
  ].join('\n')
}}];
